INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('617e9247-45b1-47d6-b787-b309b5b7d02f', 'b25b02f4-0533-483f-9a7b-c2e866e6f25d', 3, 'A Escuta do Coração', NULL, '{"intro": "A ora\u00e7\u00e3o m\u00edstica \u00e9 mais recep\u00e7\u00e3o do que emiss\u00e3o.", "prayer": "Deixe que Ele fale no centro do seu ser.", "practice": "Passe 10 minutos apenas ouvindo o som ambiente.", "reflection": "N\u00e3o fale, escute. O Mestre est\u00e1 na sala.", "journal_prompt": "Qual foi a \u00faltima coisa que Ele lhe sussurrou?"}'), ('8bb7e628-8e0b-497e-b8f0-dc9cd2f567a9', 'b25b02f4-0533-483f-9a7b-c2e866e6f25d', 4, 'O Fogo que Consome', NULL, '{"intro": "A purifica\u00e7\u00e3o d\u00f3i, mas \u00e9 ela que nos torna transparentes.", "prayer": "Pe\u00e7a para ser consumido pelo Amor.", "practice": "Agrade\u00e7a por uma dificuldade que te amadureceu.", "reflection": "O amor de Deus n\u00e3o \u00e9 um sentimento, \u00e9 um fogo purificador.", "journal_prompt": "O que em voc\u00ea ainda resiste ao fogo?"}'), ('dfbe9731-29a5-4797-9be6-9b711ac4af1a', 'b25b02f4-0533-483f-9a7b-c2e866e6f25d', 5, 'A Nuvem do Não-Saber', NULL, '{"intro": "A mente racional tem limites que a f\u00e9 deve ultrapassar.", "prayer": "Confie no escuro da f\u00e9.", "practice": "Abandone hoje o controle sobre uma situa\u00e7\u00e3o incerta.", "reflection": "Para conhec\u00ea-Lo verdadeiramente, \u00e9 preciso desaprender tudo.", "journal_prompt": "Voc\u00ea consegue amar o que n\u00e3o entende?"}'), ('d782d01e-c40c-4e75-80ff-8a3d3467f818', 'b25b02f4-0533-483f-9a7b-c2e866e6f25d', 6, 'A União Íntima', NULL, '{"intro": "A m\u00edstica \u00e9 o fim da separa\u00e7\u00e3o entre o Criador e a criatura.", "prayer": "Sinta a uni\u00e3o profunda em cada respira\u00e7\u00e3o.", "practice": "Aja hoje como se Ele estivesse fisicamente ao seu lado.", "reflection": "Eu nele e Ele em mim: um s\u00f3 cora\u00e7\u00e3o.", "journal_prompt": "Onde termina voc\u00ea e come\u00e7a Ele?"}'), ('4bae9977-bcbf-4363-8993-5c79976aa325', 'b25b02f4-0533-483f-9a7b-c2e866e6f25d', 7, 'O Transbordamento no Outro', NULL, '{"intro": "O encontro com Deus deve resultar no encontro com o irm\u00e3o.", "prayer": "Seja o canal por onde o amor dEle flui.", "practice": "Sirva a algu\u00e9m de forma oculta hoje.", "reflection": "A m\u00edstica que n\u00e3o serve n\u00e3o \u00e9 m\u00edstica, \u00e9 ego\u00edsmo.", "journal_prompt": "Como o seu encontro com Deus mudou o seu olhar para o outro?"}'), ('8f3f79a3-bd01-47c3-afe4-172187266e41', 'b2b2b2b2-3030-4000-8000-000000000002', 1, 'Dia 1 — Reconhecer', 'Semana 1: Acolher', '{"pch": "O Senhor est\u00e1 perto dos que t\u00eam o cora\u00e7\u00e3o quebrantado\u2026 Reconhecer a dor \u00e9 o primeiro passo.", "verse": "Sl 34,18", "lectio": "Leia Sl 34,17-22. Deus ouve o grito do justo.", "practice": "Escreva o que d\u00f3i. Sem filtro, sem julgamento.", "question": "Que dor voc\u00ea carrega em sil\u00eancio?"}'), ('7229c52f-8e64-48b4-ad8c-978f30cb3bb9', 'b2b2b2b2-3030-4000-8000-000000000002', 2, 'Dia 2 — Acolher', 'Semana 1: Acolher', '{"pch": "Vinde a mim, todos os cansados\u2026 Voc\u00ea n\u00e3o precisa ser forte o tempo todo.", "verse": "Mt 11,28", "lectio": "Leia Mt 11,25-30. O jugo suave.", "practice": "Permita-se sentir. Chore se precisar. Deus acolhe.", "question": "Quando foi a \u00faltima vez que voc\u00ea se permitiu chorar?"}'), ('228114be-1c58-4279-bd86-90f0aa69b48d', 'b2b2b2b2-3030-4000-8000-000000000002', 3, 'Dia 3 — Nomear', 'Semana 1: Acolher', '{"pch": "Onde est\u00e1s? Deus pergunta n\u00e3o porque n\u00e3o sabe\u2026 mas porque voc\u00ea precisa responder.", "verse": "Gn 3,9", "lectio": "Leia Gn 3,8-13. Ad\u00e3o se escondeu. Deus o buscou.", "practice": "Nomeie 3 emo\u00e7\u00f5es que voc\u00ea sente agora. Sem julg\u00e1-las.", "question": "Se sua dor tivesse um nome, qual seria?"}'), ('8d54eebc-3e64-4de2-b654-e644df39afdf', 'b2b2b2b2-3030-4000-8000-000000000002', 4, 'Dia 4 — Chorar', 'Semana 1: Acolher', '{"pch": "Jesus chorou. Se Deus chora, por que voc\u00ea n\u00e3o pode?", "verse": "Jo 11,35", "lectio": "Leia Jo 11,32-44. Jesus se comoveu antes de agir.", "practice": "Leia um salmo de lamento (Sl 42). Fa\u00e7a dele sua ora\u00e7\u00e3o.", "question": "Que l\u00e1grimas voc\u00ea segurou por tempo demais?"}'), ('533c65e5-95e8-4e3d-a3ef-9519036e8743', 'b2b2b2b2-3030-4000-8000-000000000002', 5, 'Dia 5 — Abandono', 'Semana 1: Acolher', '{"pch": "Ainda que meu pai e minha m\u00e3e me abandonem\u2026 o Senhor me acolher\u00e1.", "verse": "Sl 27,10", "lectio": "Leia Sl 27. Deus \u00e9 luz e salva\u00e7\u00e3o.", "practice": "Escreva uma carta ao seu eu crian\u00e7a. Diga o que ele precisava ouvir.", "question": "Quem te fez sentir abandonado?"}'), ('cf838250-8259-4ee5-8181-cc2b15a71541', 'b2b2b2b2-3030-4000-8000-000000000002', 6, 'Dia 6 — Rejeição', 'Semana 1: Acolher', '{"pch": "Desprezado e rejeitado\u2026 Jesus conhece a rejei\u00e7\u00e3o. Ele entende.", "verse": "Is 53,3", "lectio": "Leia Is 53,1-6. O servo sofredor.", "practice": "Identifique padr\u00f5es de rejei\u00e7\u00e3o na sua vida. Ore sobre cada um.", "question": "Que rejei\u00e7\u00e3o ainda ecoa dentro de voc\u00ea?"}'), ('3aef49a3-97c8-4f50-9fef-dfe888deb99d', 'b2b2b2b2-3030-4000-8000-000000000002', 7, 'Dia 7 — Descanso', 'Semana 1: Acolher', '{"pch": "Ele me faz repousar em pastos verdejantes\u2026 A cura come\u00e7a no descanso, n\u00e3o no esfor\u00e7o.", "verse": "Sl 23,2", "lectio": "Leia Sl 23. O Bom Pastor cuida.", "practice": "Tire 30 minutos hoje sem produtividade. Apenas seja.", "question": "Voc\u00ea tem descansado de verdade?"}'), ('ee9c9fe0-4f4b-4ccc-aceb-150a0ac29e43', 'b2b2b2b2-3030-4000-8000-000000000002', 8, 'Dia 8 — Raiva', 'Semana 2: Processar', '{"pch": "Irai-vos e n\u00e3o pequeis\u2026 A raiva n\u00e3o \u00e9 pecado. O que voc\u00ea faz com ela pode ser.", "verse": "Ef 4,26", "lectio": "Leia Ef 4,25-32. Falar a verdade em amor.", "practice": "Escreva uma carta de raiva (sem enviar). Depois, entregue a Deus.", "question": "De que voc\u00ea tem raiva e nunca admitiu?"}'), ('b46a74c9-a461-4059-bf94-083845914f4f', 'b2b2b2b2-3030-4000-8000-000000000002', 9, 'Dia 9 — Culpa', 'Semana 2: Processar', '{"pch": "Nenhuma condena\u00e7\u00e3o h\u00e1\u2026 para os que est\u00e3o em Cristo. A culpa que condena n\u00e3o vem de Deus.", "verse": "Rm 8,1", "lectio": "Leia Rm 8,1-4. Liberdade da condena\u00e7\u00e3o.", "practice": "Diga em voz alta: Eu sou perdoado. Eu estou livre.", "question": "Que culpa te persegue mesmo depois de ter sido perdoado?"}'), ('e85b59ed-a6af-4ddf-becc-eaea5b5d0400', 'b2b2b2b2-3030-4000-8000-000000000002', 10, 'Dia 10 — Vergonha', 'Semana 2: Processar', '{"pch": "Em vez da vergonha, por\u00e7\u00e3o dobrada\u2026 Deus troca sua vergonha por honra.", "verse": "Is 61,7", "lectio": "Leia Is 61,1-7. O Esp\u00edrito do Senhor cura.", "practice": "Compartilhe com Deus (em ora\u00e7\u00e3o) aquilo que esconde de todos.", "question": "De que voc\u00ea tem vergonha que nunca contou?"}'), ('c18e4986-5cf4-45f0-8643-bad413671530', 'b2b2b2b2-3030-4000-8000-000000000002', 11, 'Dia 11 — Luto', 'Semana 2: Processar', '{"pch": "Enxugar\u00e1 toda l\u00e1grima\u2026 A dor \u00e9 tempor\u00e1ria. A consola\u00e7\u00e3o \u00e9 eterna.", "verse": "Ap 21,4", "lectio": "Leia Ap 21,1-5. O novo c\u00e9u e a nova terra.", "practice": "Escreva uma despedida para o que perdeu. Permita-se sentir.", "question": "Que perda voc\u00ea ainda n\u00e3o processou?"}'), ('bc9b38b5-7633-4e61-a5aa-d6b58133c738', 'b2b2b2b2-3030-4000-8000-000000000002', 12, 'Dia 12 — Medo', 'Semana 2: Processar', '{"pch": "Deus n\u00e3o nos deu esp\u00edrito de medo\u2026 mas de poder, amor e equil\u00edbrio.", "verse": "2Tm 1,7", "lectio": "Leia 2Tm 1,6-12. Reavivar o dom de Deus.", "practice": "Enfrente um pequeno medo hoje. Celebre a vit\u00f3ria.", "question": "Que medo controla sua vida sem voc\u00ea perceber?"}'), ('43edf712-d630-4462-b3d2-8cb62fa8aa8e', 'b2b2b2b2-3030-4000-8000-000000000002', 13, 'Dia 13 — Perdoar-se', 'Semana 2: Processar', '{"pch": "Se confessarmos os nossos pecados, Ele \u00e9 fiel e justo para nos perdoar\u2026 Voc\u00ea tamb\u00e9m pode se perdoar.", "verse": "1Jo 1,9", "lectio": "Leia 1Jo 1,5-10. Andar na luz.", "practice": "Olhe no espelho e diga: Eu te perdoo. Eu te amo.", "question": "O que voc\u00ea fez que ainda n\u00e3o se perdoou?"}'), ('27d85dd7-a74c-4d01-8e0a-e90bdbbf424e', 'b2b2b2b2-3030-4000-8000-000000000002', 14, 'Dia 14 — Perdoar outros', 'Semana 2: Processar', '{"pch": "Se perdoardes\u2026 tamb\u00e9m o Pai vos perdoar\u00e1. Perdoar n\u00e3o \u00e9 esquecer \u2014 \u00e9 soltar.", "verse": "Mt 6,14", "lectio": "Leia Mt 6,12-15 e Mt 18,21-35. O servo impiedoso.", "practice": "Reze pelo nome de quem te machucou. Solte a amarra.", "question": "Quem ainda ocupa espa\u00e7o na sua dor?"}'), ('404a407c-7d20-40d5-9662-2a11188d2e77', 'b2b2b2b2-3030-4000-8000-000000000002', 15, 'Dia 15 — Nova pele', 'Semana 3: Reconstruir', '{"pch": "Eis que farei entrar em v\u00f3s o esp\u00edrito, e vivereis\u2026 Ossos secos podem viver.", "verse": "Ez 37,5", "lectio": "Leia Ez 37,1-14. O vale dos ossos secos.", "practice": "Visualize sua vida restaurada. Escreva como seria.", "question": "Que parte de voc\u00ea precisa renascer?"}'), ('18727147-0b1d-463f-a650-d85e3000493d', 'b2b2b2b2-3030-4000-8000-000000000002', 16, 'Dia 16 — Autocompaixão', 'Semana 3: Reconstruir', '{"pch": "Como um pai se compadece dos filhos\u2026 Seja gentil consigo mesmo como Deus \u00e9 com voc\u00ea.", "verse": "Sl 103,13", "lectio": "Leia Sl 103,8-14. Deus conhece nossa fragilidade.", "practice": "Hoje, trate-se como trataria seu melhor amigo.", "question": "Como voc\u00ea se trata quando falha?"}'), ('247ec458-de31-4b8d-a22c-15f26a0969e7', 'b2b2b2b2-3030-4000-8000-000000000002', 17, 'Dia 17 — Limites', 'Semana 3: Reconstruir', '{"pch": "Seja o vosso sim, sim; e o vosso n\u00e3o, n\u00e3o\u2026 Limites saud\u00e1veis protegem o que Deus cura.", "verse": "Mt 5,37", "lectio": "Leia Mt 5,33-37. Clareza nas palavras.", "practice": "Defina 1 limite que voc\u00ea vai estabelecer esta semana.", "question": "Onde voc\u00ea precisa dizer n\u00e3o para proteger sua paz?"}'), ('78f04225-0188-4a5f-9641-566f2ca54937', 'b2b2b2b2-3030-4000-8000-000000000002', 18, 'Dia 18 — Gratidão', 'Semana 3: Reconstruir', '{"pch": "Transformaste o meu pranto em dan\u00e7a\u2026 A gratid\u00e3o muda o foco da dor para a gra\u00e7a.", "verse": "Sl 30,11", "lectio": "Leia Sl 30. De lamento a louvor.", "practice": "Escreva 5 coisas boas que existem por causa de algo dif\u00edcil.", "question": "O que de bom nasceu de algo que te machucou?"}'), ('e13ea0a4-693c-4ed8-87d4-f83b33fbcc98', 'b2b2b2b2-3030-4000-8000-000000000002', 19, 'Dia 19 — Força', 'Semana 3: Reconstruir', '{"pch": "Os que esperam no Senhor renovar\u00e3o as suas for\u00e7as\u2026 A for\u00e7a vem da espera, n\u00e3o da pressa.", "verse": "Is 40,31", "lectio": "Leia Is 40,28-31. O Deus eterno n\u00e3o se cansa.", "practice": "Fa\u00e7a algo que recarregue sua energia emocional hoje.", "question": "De onde voc\u00ea tira for\u00e7a quando tudo parece demais?"}'), ('f8455191-ac40-4c0c-bec1-b628b7d118f1', 'b2b2b2b2-3030-4000-8000-000000000002', 20, 'Dia 20 — Vulnerabilidade', 'Semana 3: Reconstruir', '{"pch": "Temos esse tesouro em vasos de barro\u2026 Sua fragilidade n\u00e3o \u00e9 fraqueza \u2014 \u00e9 transpar\u00eancia.", "verse": "2Cor 4,7", "lectio": "Leia 2Cor 4,7-12. Poder na fragilidade.", "practice": "Compartilhe algo verdadeiro com algu\u00e9m de confian\u00e7a.", "question": "Com quem voc\u00ea pode ser vulner\u00e1vel?"}'), ('be9d5286-0a3e-4dbf-aa8d-f41237d8df95', 'b2b2b2b2-3030-4000-8000-000000000002', 21, 'Dia 21 — Esperança', 'Semana 3: Reconstruir', '{"pch": "O Deus da esperan\u00e7a vos encha de alegria e paz\u2026 A esperan\u00e7a \u00e9 uma pessoa, n\u00e3o um sentimento.", "verse": "Rm 15,13", "lectio": "Leia Rm 15,13. Transbordar de esperan\u00e7a.", "practice": "Escreva 3 coisas que ainda espera ver acontecer.", "question": "Em que voc\u00ea ainda espera?"}'), ('58a2a723-a8a3-44cf-9acb-7d799ed70a2d', 'b2b2b2b2-3030-4000-8000-000000000002', 22, 'Dia 22 — Recomeço', 'Semana 4: Integrar', '{"pch": "As miseric\u00f3rdias do Senhor renovam-se cada manh\u00e3\u2026 Cada dia \u00e9 um novo come\u00e7o.", "verse": "Lm 3,22-23", "lectio": "Leia Lm 3,19-26. Esperan\u00e7a no meio da ru\u00edna.", "practice": "Comece algo novo hoje \u2014 mesmo pequeno.", "question": "O que voc\u00ea gostaria de recome\u00e7ar?"}'), ('c20d1e17-3623-4448-99a6-1c8146565526', 'b2b2b2b2-3030-4000-8000-000000000002', 23, 'Dia 23 — Identidade restaurada', 'Semana 4: Integrar', '{"pch": "Eu te chamei pelo teu nome, tu \u00e9s meu\u2026 Sua identidade n\u00e3o est\u00e1 na dor \u2014 est\u00e1 em quem te criou.", "verse": "Is 43,1", "lectio": "Leia Is 43,1-7. Precioso aos olhos de Deus.", "practice": "Escreva: Eu sou mais do que aconteceu comigo porque _____", "question": "Como voc\u00ea se define al\u00e9m da sua dor?"}'), ('79b7e0cb-da66-4450-8acc-fc19c16c5348', 'b2b2b2b2-3030-4000-8000-000000000002', 24, 'Dia 24 — Propósito na dor', 'Semana 4: Integrar', '{"pch": "Todas as coisas cooperam para o bem\u2026 Sua dor tem prop\u00f3sito, mesmo quando n\u00e3o parece.", "verse": "Rm 8,28", "lectio": "Leia Rm 8,28-30. O plano de Deus.", "practice": "Escreva como sua dor pode servir a outra pessoa.", "question": "Que sentido voc\u00ea encontra na sua hist\u00f3ria?"}'), ('6352aa56-67fc-470f-a23a-9bf0366b1caf', 'b2b2b2b2-3030-4000-8000-000000000002', 25, 'Dia 25 — Cicatrizes', 'Semana 4: Integrar', '{"pch": "Jesus mostrou suas cicatrizes\u2026 Elas n\u00e3o desapareceram \u2014 se tornaram testemunho.", "verse": "Jo 20,27", "lectio": "Leia Jo 20,24-29. Tom\u00e9 tocou as feridas.", "practice": "Agrade\u00e7a por uma cicatriz. Ela prova que voc\u00ea sobreviveu.", "question": "Que cicatrizes suas contam uma hist\u00f3ria de supera\u00e7\u00e3o?"}'), ('d74e36fd-1550-42bf-a471-75f292b882a0', 'b2b2b2b2-3030-4000-8000-000000000002', 26, 'Dia 26 — Alegria', 'Semana 4: Integrar', '{"pch": "A alegria do Senhor \u00e9 a vossa for\u00e7a\u2026 A alegria n\u00e3o nega a dor \u2014 coexiste com ela.", "verse": "Ne 8,10", "lectio": "Leia Ne 8,9-12. Chorar e celebrar no mesmo dia.", "practice": "Fa\u00e7a algo que te d\u00ea alegria pura hoje.", "question": "O que te d\u00e1 alegria verdadeira?"}'), ('78ece41c-115b-42c7-b9ab-f4e888bd44c3', 'b2b2b2b2-3030-4000-8000-000000000002', 27, 'Dia 27 — Conexão', 'Semana 4: Integrar', '{"pch": "Levai as cargas uns dos outros\u2026 Cura n\u00e3o acontece no isolamento.", "verse": "Gl 6,2", "lectio": "Leia Gl 6,1-5. Comunidade na restaura\u00e7\u00e3o.", "practice": "Ligue para algu\u00e9m. Diga: preciso de voc\u00ea.", "question": "Quem voc\u00ea precisa ao seu lado neste momento?"}'), ('514f473e-a51b-4076-b0de-75285f981850', 'b2b2b2b2-3030-4000-8000-000000000002', 28, 'Dia 28 — Paz', 'Semana 4: Integrar', '{"pch": "A minha paz vos dou\u2026 n\u00e3o como o mundo a d\u00e1. Paz n\u00e3o \u00e9 aus\u00eancia de conflito \u2014 \u00e9 presen\u00e7a de Deus.", "verse": "Jo 14,27", "lectio": "Leia Jo 14,25-31. O Consolador vem.", "practice": "Identifique o ladr\u00e3o de paz. Entregue-o em ora\u00e7\u00e3o.", "question": "O que te rouba a paz?"}'), ('275c740d-e9b2-456f-84d3-7e2d2e764762', 'b2b2b2b2-3030-4000-8000-000000000002', 29, 'Dia 29 — Testemunho', 'Semana 4: Integrar', '{"pch": "Tirou-me do po\u00e7o\u2026 e p\u00f4s nos meus l\u00e1bios um c\u00e2ntico novo. Sua hist\u00f3ria \u00e9 seu testemunho.", "verse": "Sl 40,2-3", "lectio": "Leia Sl 40,1-5. Da espera ao louvor.", "practice": "Escreva seu testemunho em 5 frases.", "question": "O que voc\u00ea diria a algu\u00e9m que est\u00e1 onde voc\u00ea estava?"}'), ('a80d565d-c6d9-4f86-b941-cec6e83d1841', 'b2b2b2b2-3030-4000-8000-000000000002', 30, 'Dia 30 — Inteiro', 'Semana 4: Integrar', '{"pch": "Sara os quebrantados de cora\u00e7\u00e3o\u2026 e liga-lhes as feridas. Voc\u00ea n\u00e3o est\u00e1 quebrado. Est\u00e1 sendo restaurado.", "verse": "Sl 147,3", "lectio": "Leia Sl 147,1-7. Deus conta as estrelas e sara os cora\u00e7\u00f5es.", "practice": "Releia suas reflex\u00f5es dos 30 dias. Escreva uma carta de gratid\u00e3o a si mesmo.", "question": "Quem voc\u00ea se tornou atrav\u00e9s da dor?"}'), ('f75b8079-8b74-4a7d-b250-c3e7b88ced2b', 'c1c2c3d4-3030-4000-8000-000000000030', 1, 'Perceber', 'Semana 1 — Despertar', '{"pch": "A pressa revela\u2026 onde a confian\u00e7a ainda n\u00e3o chegou.", "verse": "Mt 6,25-34", "lectio": "Leia o texto lentamente. Pare na palavra que incomoda. Pergunte: por que essa palavra me toca?", "practice": "Escreva no di\u00e1rio: qual \u00e1rea da minha vida estou tentando controlar com pressa?", "question": "O que est\u00e1 te acelerando?"}'), ('986ec036-538c-4d29-9ce3-d78185c46588', 'c1c2c3d4-3030-4000-8000-000000000030', 2, 'Pausar', 'Semana 1 — Despertar', '{"pch": "Nem todo movimento \u00e9 progresso\u2026 \u00e0s vezes \u00e9 fuga.", "verse": "Sl 46,10", "lectio": "Sente-se em sil\u00eancio por 3 minutos antes de ler. Depois leia o salmo duas vezes.", "practice": "Identifique uma a\u00e7\u00e3o que voc\u00ea repete por ansiedade, n\u00e3o por necessidade.", "question": "Do que voc\u00ea est\u00e1 fugindo?"}'), ('8040b3ca-8cce-4c4e-8e65-840a0d18de35', 'c1c2c3d4-3030-4000-8000-000000000030', 3, 'Sentir', 'Semana 1 — Despertar', '{"pch": "Sentir n\u00e3o \u00e9 fraqueza\u2026 \u00e9 acesso.", "verse": "Sl 34,18", "lectio": "Leia o vers\u00edculo e pergunte: onde est\u00e1 essa dor em mim agora?", "practice": "Nomeie tr\u00eas emo\u00e7\u00f5es que voc\u00ea sentiu hoje, sem julgamento.", "question": "O que voc\u00ea evita sentir?"}'), ('77fca868-67b4-4f17-91cd-c74cb2546161', 'c1c2c3d4-3030-4000-8000-000000000030', 4, 'Nomear', 'Semana 1 — Despertar', '{"pch": "Aquilo que voc\u00ea n\u00e3o nomeia\u2026 te controla.", "verse": "Gn 2,19-20", "lectio": "Assim como Ad\u00e3o nomeou cada criatura, nomeie o que vive dentro de voc\u00ea.", "practice": "Escreva: qual medo, h\u00e1bito ou ferida eu ainda n\u00e3o nomeei?", "question": "O que voc\u00ea ainda n\u00e3o enfrentou?"}'), ('45d795f0-f382-43ac-9a04-101bbbbd2a76', 'c1c2c3d4-3030-4000-8000-000000000030', 5, 'Aceitar', 'Semana 1 — Despertar', '{"pch": "Aceitar n\u00e3o \u00e9 desistir\u2026 \u00e9 parar de lutar contra o que j\u00e1 \u00e9.", "verse": "Rm 8,28", "lectio": "Leia e pergunte: o que Deus pode estar fazendo com aquilo que eu rejeito?", "practice": "Escreva uma coisa que voc\u00ea precisa parar de resistir.", "question": "O que voc\u00ea resiste?"}'), ('50f1689c-f250-4f15-870a-89b443a270d5', 'c1c2c3d4-3030-4000-8000-000000000030', 6, 'Silenciar', 'Semana 1 — Despertar', '{"pch": "No sil\u00eancio\u2026 a verdade sobe.", "verse": "1Rs 19,11-13", "lectio": "Fique 5 minutos em sil\u00eancio antes de ler. O que surgiu?", "practice": "Reserve 10 minutos de sil\u00eancio completo hoje.", "question": "O que aparece quando voc\u00ea para?"}'), ('0288ddc5-3827-4163-be3a-5e8e4458e3bb', 'c1c2c3d4-3030-4000-8000-000000000030', 7, 'Observar', 'Semana 1 — Despertar', '{"pch": "Voc\u00ea n\u00e3o \u00e9 o pensamento\u2026 \u00e9 quem percebe.", "verse": "Lc 12,22-26", "lectio": "Leia e observe: quais pensamentos autom\u00e1ticos governam suas decis\u00f5es?", "practice": "Anote 3 pensamentos recorrentes que podem ser cren\u00e7as, n\u00e3o verdades.", "question": "O que voc\u00ea est\u00e1 acreditando sem questionar?"}'), ('b012f24c-4a6b-4fbb-9076-34f2909d1246', 'c1c2c3d4-3030-4000-8000-000000000030', 8, 'Soltar Controle', 'Semana 2 — Desconstruir', '{"pch": "Controlar \u00e9 a forma mais elegante de desconfiar.", "verse": "Pv 3,5-6", "lectio": "Leia e pergunte: em que \u00e1rea eu confio mais em mim do que em Deus?", "practice": "Escolha uma coisa para n\u00e3o controlar hoje. Observe o que sente.", "question": "O que voc\u00ea n\u00e3o consegue largar?"}'), ('ab2806d7-2b4c-43b2-a7e4-c491681c8b11', 'c1c2c3d4-3030-4000-8000-000000000030', 9, 'Enfrentar Medo', 'Semana 2 — Desconstruir', '{"pch": "O medo n\u00e3o \u00e9 sinal de fraqueza\u2026 \u00e9 sinal de fronteira.", "verse": "Is 41,10", "lectio": "Leia a promessa. Pergunte: qual medo Deus est\u00e1 me convidando a atravessar?", "practice": "Nomeie seu maior medo atual e escreva o que aconteceria se ele n\u00e3o existisse.", "question": "Qual medo te paralisa?"}'), ('c6550de4-ada8-4202-b793-7b28ad948975', 'c1c2c3d4-3030-4000-8000-000000000030', 10, 'Identificar Padrões', 'Semana 2 — Desconstruir', '{"pch": "Voc\u00ea chama de personalidade\u2026 mas pode ser repeti\u00e7\u00e3o.", "verse": "Rm 7,15-20", "lectio": "Paulo descreve a luta interior. Qual luta \u00e9 sua?", "practice": "Identifique um padr\u00e3o que se repete em relacionamentos, trabalho ou emo\u00e7\u00f5es.", "question": "Qual padr\u00e3o voc\u00ea repete sem perceber?"}'), ('698dfc1a-e44e-42d0-b4fe-66fc6f0cdc37', 'c1c2c3d4-3030-4000-8000-000000000030', 11, 'Romper Crenças', 'Semana 2 — Desconstruir', '{"pch": "A verdade liberta\u2026 mas primeiro incomoda.", "verse": "Jo 8,32", "lectio": "Leia e pergunte: qual mentira eu acreditei sobre mim?", "practice": "Escreva uma cren\u00e7a limitante e reescreva-a \u00e0 luz da Palavra.", "question": "Qual cren\u00e7a sobre voc\u00ea mesmo precisa ser revisada?"}'), ('4affb73b-d4d7-4845-b7cc-a5c1f89739a5', 'c1c2c3d4-3030-4000-8000-000000000030', 12, 'Perdoar', 'Semana 2 — Desconstruir', '{"pch": "Perdoar n\u00e3o \u00e9 esquecer\u2026 \u00e9 soltar a corda que te prende ao outro.", "verse": "Mt 6,14-15", "lectio": "Leia e sinta: qual peso do passado voc\u00ea ainda carrega?", "practice": "Escreva uma carta de perd\u00e3o \u2014 n\u00e3o precisa enviar.", "question": "Quem voc\u00ea ainda n\u00e3o perdoou?"}'), ('3a39399b-5772-45fb-b820-48aff4098714', 'c1c2c3d4-3030-4000-8000-000000000030', 13, 'Liberar Peso', 'Semana 2 — Desconstruir', '{"pch": "Carregar demais n\u00e3o \u00e9 for\u00e7a\u2026 \u00e9 desconfian\u00e7a.", "verse": "Mt 11,28-30", "lectio": "Jesus convida ao descanso. O que voc\u00ea precisa entregar?", "practice": "Fa\u00e7a uma lista do que pesa e marque o que n\u00e3o depende de voc\u00ea.", "question": "O que pesa em voc\u00ea que n\u00e3o \u00e9 seu para carregar?"}'), ('272da72e-2655-4fb8-852c-23383d4f8a62', 'c1c2c3d4-3030-4000-8000-000000000030', 14, 'Desapegar', 'Semana 2 — Desconstruir', '{"pch": "Enquanto voc\u00ea olha para tr\u00e1s\u2026 n\u00e3o enxerga o que est\u00e1 \u00e0 frente.", "verse": "Fl 3,13-14", "lectio": "Paulo esquece o que ficou para tr\u00e1s. O que voc\u00ea precisa deixar?", "practice": "Escolha uma mem\u00f3ria, h\u00e1bito ou v\u00ednculo para soltar hoje.", "question": "O que do passado ainda te define?"}'), ('86d859f0-cfea-4b42-a4b5-b15ae072728b', 'c1c2c3d4-3030-4000-8000-000000000030', 15, 'Nova Visão', 'Semana 3 — Reconstruir', '{"pch": "Voc\u00ea n\u00e3o precisa de uma nova chance\u2026 precisa de novos olhos.", "verse": "2Cor 5,17", "lectio": "Leia e pergunte: o que significa ser nova criatura para mim hoje?", "practice": "Escreva como seria seu dia se voc\u00ea acreditasse plenamente nisso.", "question": "O que mudaria se voc\u00ea se visse como Deus te v\u00ea?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;